//! Tests of `waveform.rs` (W1h item H3a). Every behaviour starts with a test here that failed first.
//!
//! The golden table (`waveform_golden.rs`, generated by `scripts/gen-signal-gen-golden.ts`) is classic's own
//! `signalGenVoltage` on classic's own parse. Deterministic shapes are compared bit for bit; noise by Q-O71's
//! bound; the schedules against the contract's expressions evaluated in TS, and against the voltage function
//! itself between events.

use super::waveform_golden::{CASES, EVENTS, ROWS};
use super::*;

// ---- helpers ------------------------------------------------------------------------------------------------

fn ulp_key(v: f64) -> i64 {
    let bits = v.to_bits() as i64;
    if bits < 0 {
        i64::MIN.wrapping_sub(bits)
    } else {
        bits
    }
}

fn ulps(a: f64, b: f64) -> u64 {
    (ulp_key(a) as i128 - ulp_key(b) as i128).unsigned_abs() as u64
}

fn case_index(name: &str) -> usize {
    CASES.iter().position(|c| c.0 == name).unwrap_or_else(|| panic!("no golden case {name}"))
}

fn case(name: &str) -> (&'static [f64; 13], &'static [f64]) {
    let i = case_index(name);
    (&CASES[i].1, CASES[i].2)
}

fn shape_of(params: &[f64; 13]) -> u32 {
    params[WAVEFORM] as u32
}

fn shape_name(shape: u32) -> &'static str {
    ["dc", "sine", "square", "pulse", "triangle", "ramp", "pwl", "noise"][shape as usize]
}

/// A default 1 kHz generator of one shape, params overridden by `(index, value)`.
fn params_of(shape: u32, overrides: &[(usize, f64)]) -> [f64; 13] {
    let mut p = [shape as f64, 2.5, 2.5, 1000.0, 0.0, 0.5, 0.0, 1e-6, 1e-6, 5e-4, 1.0, 1.0, 50.0];
    for &(i, v) in overrides {
        p[i] = v;
    }
    p
}

// ---- the voltage function against classic, bit for bit -----------------------------------------------------------

#[test]
fn golden_covers_every_shape_and_the_table_is_not_empty() {
    assert!(ROWS.len() > 2000, "the generator must have run");
    let mut seen = [false; 8];
    for c in CASES {
        seen[c.1[WAVEFORM] as usize] = true;
    }
    assert!(seen.iter().all(|&s| s), "a shape has no golden case: {seen:?}");
}

#[test]
fn deterministic_shapes_match_classic_bit_for_bit() {
    let mut max_ulp = [0u64; 8];
    let mut worst: Vec<String> = Vec::new();
    for &(c, t, want, _unit) in ROWS {
        let (name, params, blob) = (&CASES[c].0, &CASES[c].1, CASES[c].2);
        let shape = shape_of(params);
        // Sine and noise call libm (`sin`; `ln` and `cos`), which V8 and Rust round alike only almost always:
        // their own tests below.
        if shape == SHAPE_NOISE || shape == SHAPE_SINE {
            continue;
        }
        let got = signal_gen_voltage(params, blob, t);
        let d = ulps(got, want);
        max_ulp[shape as usize] = max_ulp[shape as usize].max(d);
        if d != 0 && worst.len() < 12 {
            worst.push(format!("{name} t={t:e}: got {got:e}, want {want:e}, {d} ulp"));
        }
    }
    let report: Vec<String> =
        (0..7).filter(|&s| s != SHAPE_SINE).map(|s| format!("{}:{}", shape_name(s), max_ulp[s as usize])).collect();
    eprintln!("max ulp deviation per shape: {}", report.join(" "));
    assert!(worst.is_empty(), "not bit for bit ({}):\n{}", report.join(" "), worst.join("\n"));
}

/// A sine calls `Math.sin`, which V8 takes from a glibc-derived implementation and Rust from its libm (or the
/// host's); the argument `2 pi f t' + phase` is bit-identical, so they differ only inside `sin`. Measured over
/// the full 19k-row grid this table was thinned from: native macOS and wasm32 both differ on well under 1 % of rows,
/// by at most 1 ulp of the sine value (wasm32: 14 of 2327 rows; native 67), and every such row is kept here.
/// Ruled R62: `SINE_ULP_BOUND`, 1 ulp on the sine value and, on the node value, `amplitude * 1 ulp` plus one
/// rounding each of the product and the sum (Q-O71's form).
const SINE_ULP_BOUND: u64 = 1;

#[test]
fn sine_value_is_within_the_ruled_one_ulp_of_classic() {
    let (mut max_ulp, mut differing, mut n) = (0, 0, 0);
    let mut max_volt_ulp = 0;
    for &(c, t, want, unit) in ROWS {
        let (params, blob) = (&CASES[c].1, CASES[c].2);
        if shape_of(params) != SHAPE_SINE {
            continue;
        }
        let mut unit_params = *params;
        unit_params[OFFSET] = 0.0;
        unit_params[AMPLITUDE] = 1.0;
        let got_unit = signal_gen_voltage(&unit_params, blob, t);
        let d = ulps(got_unit, unit);
        n += 1;
        differing += usize::from(d != 0);
        max_ulp = max_ulp.max(d);
        assert!(d <= SINE_ULP_BOUND, "{} t={t:e}: sine {got_unit:e} vs classic {unit:e}: {d} ulp", CASES[c].0);

        let got = signal_gen_voltage(params, blob, t);
        max_volt_ulp = max_volt_ulp.max(ulps(got, want));
        let product = params[AMPLITUDE] * unit;
        let half_ulp = |x: f64| (f64::from_bits(x.abs().to_bits() + 1) - x.abs()) / 2.0;
        let one_ulp = |x: f64| f64::from_bits(x.abs().to_bits() + 1) - x.abs();
        let bound = params[AMPLITUDE] * one_ulp(unit) + half_ulp(product) + half_ulp(want) + half_ulp(got);
        assert!((got - want).abs() <= bound, "{} t={t:e}: {got:e} vs {want:e}, bound {bound:e}", CASES[c].0);
    }
    eprintln!("sine: {n} rows, {differing} differ, max sine deviation {max_ulp} ulp, max node-value deviation {max_volt_ulp} ulp");
    assert!(n > 300);
}

/// Q-O71: with the same bucket index a core variate may differ from classic's by at most 4 ulp.
#[test]
fn noise_unit_is_within_four_ulp_of_classic() {
    let mut max_ulp = 0;
    let mut n = 0;
    for &(c, t, _want, unit) in ROWS {
        let (params, blob) = (&CASES[c].1, CASES[c].2);
        if shape_of(params) != SHAPE_NOISE {
            continue;
        }
        let mut unit_params = *params;
        unit_params[OFFSET] = 0.0;
        unit_params[AMPLITUDE] = 1.0;
        let got = signal_gen_voltage(&unit_params, blob, t);
        let d = ulps(got, unit);
        max_ulp = max_ulp.max(d);
        n += 1;
        assert!(d <= 4, "{} t={t:e}: variate {got:e} vs classic {unit:e}: {d} ulp", CASES[c].0);
    }
    eprintln!("noise: {n} rows, max variate deviation {max_ulp} ulp");
    assert!(n > 300);
}

/// Q-O71 on the node value: `8.9e-16 * |amplitude * unit|` plus one rounding each of the product and the sum.
#[test]
fn noise_voltage_is_within_the_ruled_bound() {
    for &(c, t, want, unit) in ROWS {
        let (params, blob) = (&CASES[c].1, CASES[c].2);
        if shape_of(params) != SHAPE_NOISE {
            continue;
        }
        let got = signal_gen_voltage(params, blob, t);
        let product = params[AMPLITUDE] * unit;
        let half_ulp = |x: f64| (f64::from_bits(x.abs().to_bits() + 1) - x.abs()) / 2.0;
        let bound = 4.0 * 2f64.powi(-52) * product.abs() + half_ulp(product) + half_ulp(want) + half_ulp(got);
        assert!((got - want).abs() <= bound, "{} t={t:e}: {got:e} vs {want:e}, bound {bound:e}", CASES[c].0);
    }
}

#[test]
fn noise_bucket_boundary_is_one_picosecond_early_and_counted_from_the_delay() {
    let (params, blob) = case("noise/seed-2"); // delay 3.3e-4
    let delay = params[DELAY];
    let unit_of = |t: f64| signal_gen_voltage(params, blob, t);
    // Inside bucket 0 up to the guard, then bucket 1: the value changes across `delay + 1e-4 - 1e-12`.
    let before = unit_of(delay + 1e-4 - 3e-12);
    let after = unit_of(delay + 1e-4 - 0.5e-12);
    let next = unit_of(delay + 1e-4 + 5e-5);
    assert_ne!(before, after);
    assert_eq!(after, next);
    // Before the delay the generator holds bucket 0, as at t' = 0.
    assert_eq!(unit_of(0.0), unit_of(delay - 1e-9));
    assert_eq!(unit_of(0.0), unit_of(delay));
}

#[test]
fn noise_seed_zero_and_negative_zero_hash_alike() {
    // JS `String(-0)` is "0"; Rust would print "-0". Math.round(-0.3) is -0 in classic's parse.
    assert_eq!(noise_unit(-0.0, 5.0).to_bits(), noise_unit(0.0, 5.0).to_bits());
}

#[test]
fn noise_is_deterministic_per_seed_and_bucket() {
    let a = noise_unit(1.0, 12.0);
    assert_eq!(a.to_bits(), noise_unit(1.0, 12.0).to_bits());
    assert_ne!(a.to_bits(), noise_unit(2.0, 12.0).to_bits());
    assert_ne!(a.to_bits(), noise_unit(1.0, 13.0).to_bits());
}

#[test]
fn noise_has_zero_mean_and_unit_rms_over_20000_buckets() {
    // Spec 8.12.4 (probe P1e): mean -0.0022, RMS 0.9967 for seed 1.
    let (mut sum, mut sq) = (0.0, 0.0);
    for b in 0..20_000 {
        let u = noise_unit(1.0, b as f64);
        sum += u;
        sq += u * u;
    }
    assert!((sum / 20_000.0 - -0.0022).abs() < 5e-4, "mean {}", sum / 20_000.0);
    assert!(((sq / 20_000.0).sqrt() - 0.9967).abs() < 5e-4, "rms {}", (sq / 20_000.0).sqrt());
}

#[test]
fn a_bucket_too_large_for_js_to_print_in_decimal_is_nan_not_a_wrong_draw() {
    assert!(noise_unit(1.0, 1e21).is_nan());
    assert!(noise_unit(1.0, 1e20).is_finite());
}

// ---- the quirks classic has and the port keeps --------------------------------------------------------------------

#[test]
fn before_the_delay_a_sine_holds_its_t0_value_not_the_offset() {
    // Spec 8.12.4, probe P1c: phase 90 with a 1 ms delay holds 5 V until 1 ms.
    let (params, blob) = case("sine/phase90-delay1ms");
    assert_eq!(signal_gen_voltage(params, blob, 0.0), 2.5 + 2.5 * 1.0);
    assert_eq!(signal_gen_voltage(params, blob, 9.99e-4), 5.0);
}

#[test]
fn dc_ignores_amplitude_and_pwl_ignores_offset_amplitude_and_delay() {
    let (dc, blob) = case("dc/offset-amplitude-ignored");
    assert_eq!(signal_gen_voltage(dc, blob, 123.0), 3.3);
    let (pwl, blob) = case("pwl/negative-times-delay-ignored");
    assert_eq!(signal_gen_voltage(pwl, blob, -5.0), 1.0);
    assert_eq!(signal_gen_voltage(pwl, blob, 0.0), 0.0);
    assert_eq!(signal_gen_voltage(pwl, blob, 1.0), 2.0);
}

#[test]
fn pwl_vertical_step_reads_the_earlier_authored_value_at_the_instant() {
    // Probe P1d: 5 V at 1 ms, then just after it the later value's line.
    let (params, blob) = case("pwl/vertical-step");
    assert_eq!(signal_gen_voltage(params, blob, 1e-3), 5.0);
    let after = signal_gen_voltage(params, blob, 1e-3 + 1e-9);
    assert!((after - 2.0).abs() < 1e-5, "{after}");
}

#[test]
fn an_empty_pwl_table_is_the_offset() {
    let (params, blob) = case("pwl/empty-is-offset");
    assert_eq!(signal_gen_voltage(params, blob, 5.0), 1.25);
}

// ---- schedules: against the contract's expressions, bit for bit -----------------------------------------------

#[test]
fn event_times_and_levels_match_the_contract_expressions_exactly() {
    assert!(EVENTS.len() > 300);
    for &(c, k, time, level) in EVENTS {
        let (params, blob) = (&CASES[c].1, CASES[c].2);
        let sched = Schedule::new(params, blob);
        let ev = sched.event(k).unwrap_or_else(|| panic!("{} has no event {k}", CASES[c].0));
        assert_eq!(ev.time.to_bits(), time.to_bits(), "{} event {k} time {:e} vs {time:e}", CASES[c].0, ev.time);
        let expected_level = if shape_of(params) == SHAPE_NOISE {
            // The golden holds the bucket index; the level is that bucket's draw.
            params[OFFSET] + params[AMPLITUDE] * noise_unit(params[SEED], level)
        } else {
            level
        };
        assert_eq!(ev.level.to_bits(), expected_level.to_bits(), "{} event {k} level", CASES[c].0);
    }
}

// ---- schedules: against the voltage function ----------------------------------------------------------------------

/// The events of `sched` from `from` for `count`, with the invariant that times never fall. A pulse whose cycle
/// exactly fills its period is W1f's own exception: the fall's end `base_c + per` and the next rise's start
/// `td + (c + 1) * per` are one instant computed two ways, and can be one ulp apart in either order.
fn walk(sched: &Schedule, from: u64, count: u64) -> Vec<SgEvent> {
    let mut out: Vec<SgEvent> = Vec::new();
    for k in from..from + count {
        let Some(ev) = sched.event(k) else { break };
        if let Some(prev) = out.last() {
            let slack = if sched.shape == SHAPE_PULSE { 2.0 * f64::EPSILON * prev.time.abs() } else { 0.0 };
            assert!(ev.time >= prev.time - slack, "event {k}: time {:e} falls below {:e}", ev.time, prev.time);
        }
        out.push(ev);
    }
    out
}

/// At the midpoint between two events the voltage function reads the level the first event set (a constant run)
/// or its straight line (a linear run). `slack` is the test's allowance for a line against classic's own
/// expression, in volts per volt of swing: both are a handful of ulps apart, never more.
fn assert_between_events(name: &str, sched: &Schedule, events: &[SgEvent], swing: f64) {
    let mut worst = 0.0f64;
    for pair in events.windows(2) {
        let (a, b) = (&pair[0], &pair[1]);
        if !(b.time > a.time) {
            continue;
        }
        let mid = a.time + (b.time - a.time) / 2.0;
        // A gap of a few ulps of the time has no interior to probe.
        if !(mid > a.time && mid < b.time) || (b.time - a.time) < 64.0 * f64::EPSILON * b.time.abs() {
            continue;
        }
        let got = sched.voltage(mid);
        let want = match a.run {
            Some(run) => run.value(mid),
            None => a.level,
        };
        let err = (got - want).abs();
        worst = worst.max(err);
        // A line against classic's own expression is a few ulps of the swing apart, plus the slope times the
        // rounding of the time itself (an ulp of 3e7 s is 3.7 ns, and a 1 Hz ramp climbs 10 V/s).
        let slope = a.run.map_or(0.0, |r| (r.v_to - r.v_from).abs() / r.len);
        let time_ulp = f64::from_bits(mid.abs().to_bits() + 1) - mid.abs();
        let tol = if a.run.is_some() { 1e-9 * swing.max(1.0) + 4.0 * slope * time_ulp } else { 0.0 };
        assert!(err <= tol, "{name}: between {:e} and {:e} (event {:?}): voltage {got:e}, schedule {want:e}", a.time, b.time, a.kind);
    }
    eprintln!("{name}: {} intervals, worst gap between voltage and schedule {worst:e}", events.len().saturating_sub(1));
}

#[test]
fn the_schedule_agrees_with_the_voltage_function_between_events() {
    let names = [
        "square/default-1k",
        "square/duty-0.01",
        "square/duty-0.99-clamped",
        "square/phase90",
        "square/phase-450",
        "square/phase-630-negative-offset",
        "square/phase720-delay",
        "square/100kHz",
        "square/3Hz",
        "triangle/default",
        "triangle/phase90",
        "triangle/phase-450",
        "triangle/phase-630-negative-offset",
        "triangle/delay-phase180",
        "triangle/50Hz",
        "ramp/default",
        "ramp/phase90",
        "ramp/phase-450",
        "ramp/phase-630-negative-offset",
        "ramp/1Hz-delay",
        "ramp/100kHz",
        "pulse/default",
        "pulse/slow-ramps",
        "pulse/delay-0.5ms",
        "pulse/exact-fill",
        "pulse/50Hz-wide",
        "pwl/simple",
        "pwl/vertical-step",
        "pwl/unsorted",
        "pwl/70-points-capped",
        "noise/seed-1",
        "noise/seed-2",
        "noise/delay-huge",
    ];
    for name in names {
        let (params, blob) = case(name);
        let sched = Schedule::new(params, blob);
        let swing = 2.0 * params[AMPLITUDE];
        // From the start, and from a long way out where index arithmetic matters (1e3 s onward).
        for &t0 in &[0.0, 1e3, 86400.5, 3.1536e7] {
            if shape_of(params) == SHAPE_PWL && t0 > 0.0 {
                continue;
            }
            let from = sched.first_event_after(t0).unwrap_or_else(|| panic!("{name}: no event after {t0}"));
            let start = from.saturating_sub(3);
            let events = walk(&sched, start, 24);
            assert!(events.len() >= 2, "{name}");
            assert_between_events(&format!("{name} @ {t0:e}"), &sched, &events, swing);
        }
    }
}

#[test]
fn first_event_after_is_the_first_event_strictly_after_t0() {
    for name in ["square/default-1k", "square/phase-630-negative-offset", "triangle/phase90", "ramp/phase-450", "pulse/default", "pulse/slow-ramps", "pwl/simple", "noise/seed-1", "square/duty-0.99-clamped"] {
        let (params, blob) = case(name);
        let sched = Schedule::new(params, blob);
        let probes = |ev: &SgEvent| {
            let below = if ev.time > 0.0 { f64::from_bits(ev.time.to_bits() - 1) } else { -1e-9 };
            [ev.time, f64::from_bits(ev.time.to_bits() + 1), below]
        };
        for k in 0..30 {
            let Some(ev) = sched.event(k) else { break };
            for t0 in probes(&ev) {
                let Some(first) = sched.first_event_after(t0) else {
                    // Only a finite schedule runs out: a table past its last knot.
                    assert_eq!(shape_of(params), SHAPE_PWL, "{name}: none after {t0:e}");
                    assert!((0..200).all(|k| sched.event(k).map_or(true, |e| e.time <= t0)), "{name}");
                    continue;
                };
                let at = sched.event(first).unwrap();
                assert!(at.time > t0, "{name}: event {first} at {:e} is not after {t0:e}", at.time);
                if first > 0 {
                    let prev = sched.event(first - 1).unwrap();
                    assert!(prev.time <= t0, "{name}: event {} at {:e} is after {t0:e} but was skipped", first - 1, prev.time);
                }
            }
        }
    }
}

#[test]
fn an_edge_instant_takes_the_edges_own_level_never_the_accident_of_the_float() {
    // Probe P1f: at 1 kHz, 1468 of 3000 rising instants m * 1e-3 read LOW in classic. The schedule has the edge
    // at its computed time with its own level, and `load_state` there applies it.
    let (params, blob) = case("square/default-1k");
    let sched = Schedule::new(params, blob);
    let mut checked = 0;
    for m in 1..300u64 {
        let t0 = m as f64 * 1e-3;
        let (level, next) = sched.load_state(t0);
        let applied = next.unwrap();
        // The last applied event is the one before `next`.
        let last = sched.event(applied - 1).unwrap();
        assert!(last.time <= t0);
        assert_eq!(level.value.to_bits(), last.level.to_bits(), "t0 {t0:e}");
        // Away from an edge the level is classic's own.
        let mid = t0 + 2.5e-4;
        let (mid_level, _) = sched.load_state(mid);
        assert_eq!(mid_level.value, sched.voltage(mid));
        checked += 1;
    }
    assert_eq!(checked, 299);
}

#[test]
fn load_state_is_classics_value_between_events_for_every_shape() {
    for name in ["dc/default", "sine/default-1k", "sine/phase90-delay1ms", "square/phase90", "triangle/phase-450", "ramp/phase-630-negative-offset", "pulse/slow-ramps", "pulse/default", "pwl/simple", "pwl/empty-is-offset", "noise/seed-1", "noise/seed-2"] {
        let (params, blob) = case(name);
        let sched = Schedule::new(params, blob);
        for &t0 in &[0.0, 2.37e-4, 1.3e-3, 7.771e-3] {
            let (level, next) = sched.load_state(t0);
            let want = sched.voltage(t0);
            // A linear run reads the line through classic's own value; a constant one the event level.
            let tol = if level.run.is_some() { 1e-9 } else { 0.0 };
            assert!((level.value - want).abs() <= tol, "{name} t0={t0:e}: load {:e}, classic {want:e}", level.value);
            if let Some(k) = next {
                assert!(sched.event(k).unwrap().time > t0, "{name}");
            }
        }
    }
}

#[test]
fn past_the_largest_resolvable_index_there_is_no_schedule_and_the_value_is_classics() {
    let (params, blob) = case("square/default-1k");
    let sched = Schedule::new(params, blob);
    assert_eq!(sched.first_event_after(1e30), None);
    let (level, next) = sched.load_state(1e30);
    assert_eq!(next, None);
    assert_eq!(level.value.to_bits(), sched.voltage(1e30).to_bits());
}

// ---- schedules: what each shape emits ---------------------------------------------------------------------------

#[test]
fn dc_has_no_events_and_the_other_shapes_name_their_class() {
    let (dc, b) = case("dc/default");
    assert_eq!(Schedule::new(dc, b).event(0), None);
    assert_eq!(Schedule::new(dc, b).first_event_after(0.0), None);
    assert_eq!(Schedule::new(dc, b).class(), ShapeClass::Constant);
    for (name, class) in [
        ("sine/default-1k", ShapeClass::Sine),
        ("square/default-1k", ShapeClass::Constant),
        ("noise/seed-1", ShapeClass::Constant),
        ("triangle/default", ShapeClass::Linear),
        ("ramp/default", ShapeClass::Linear),
        ("pwl/simple", ShapeClass::Linear),
        // W1f Q5: a pulse ramp of 1 us against a 500 us flat top is a midpoint step; 100 us of 300 us is resolved.
        ("pulse/default", ShapeClass::Constant),
        ("pulse/slow-ramps", ShapeClass::Linear),
        // A table of fewer than two points never moves.
        ("pwl/single-point", ShapeClass::Constant),
        ("pwl/empty-is-offset", ShapeClass::Constant),
    ] {
        let (p, blob) = case(name);
        assert_eq!(Schedule::new(p, blob).class(), class, "{name}");
    }
}

#[test]
fn a_sine_has_one_start_event_at_the_delay() {
    let (p, blob) = case("sine/phase90-delay1ms");
    let sched = Schedule::new(p, blob);
    let ev = sched.event(0).unwrap();
    assert_eq!((ev.time, ev.kind, ev.level), (1e-3, EventKind::Start, 5.0));
    assert_eq!(sched.event(1), None);
    assert_eq!(sched.first_event_after(0.5e-3), Some(0));
    assert_eq!(sched.first_event_after(1e-3), None);
}

#[test]
fn square_edges_alternate_with_the_edges_own_level_and_skip_those_at_or_before_the_delay() {
    // 1 kHz, 50 %, phase 0, no delay: the rise at 0 is the hold level, so the first event is the fall at 0.5 ms.
    let (p, blob) = case("square/default-1k");
    let sched = Schedule::new(p, blob);
    let e0 = sched.event(0).unwrap();
    let e1 = sched.event(1).unwrap();
    let e2 = sched.event(2).unwrap();
    assert_eq!((e0.time, e0.kind, e0.level), (0.5 * 1e-3, EventKind::Edge, 2.5 - 2.5));
    assert_eq!((e1.time, e1.level), (1e-3, 5.0));
    assert_eq!((e2.time, e2.level), (1e-3 + 0.5 * 1e-3, 0.0));
    assert!(e0.run.is_none());
    // The hold level is HIGH: nothing applied at load before the first fall.
    let (level, next) = sched.load_state(0.0);
    assert_eq!((level.value, next), (5.0, Some(0)));
}

#[test]
fn a_ramp_resets_to_the_bottom_with_a_new_run_each_period() {
    let (p, blob) = case("ramp/default");
    let sched = Schedule::new(p, blob);
    let start = sched.event(0).unwrap();
    assert_eq!((start.time, start.kind, start.level), (0.0, EventKind::Start, 0.0));
    let run = start.run.unwrap();
    assert_eq!((run.t0, run.v_from, run.v_to), (0.0, 0.0, 5.0));
    assert_eq!(run.len, 1e-3);
    let reset = sched.event(1).unwrap();
    assert_eq!((reset.time, reset.kind, reset.level), (1e-3, EventKind::Edge, 0.0));
    let run = reset.run.unwrap();
    assert_eq!((run.t0, run.len, run.v_from, run.v_to), (1e-3, 1e-3, 0.0, 5.0));
}

#[test]
fn a_triangle_has_a_corner_at_each_trough_and_peak() {
    let (p, blob) = case("triangle/default");
    let sched = Schedule::new(p, blob);
    let start = sched.event(0).unwrap();
    assert_eq!((start.time, start.kind, start.level), (0.0, EventKind::Start, 0.0));
    // From the trough at t' = 0 it rises to the peak half a period on.
    let run = start.run.unwrap();
    assert_eq!((run.t0, run.len, run.v_from, run.v_to), (0.0, 5e-4, 0.0, 5.0));
    let peak = sched.event(1).unwrap();
    assert_eq!((peak.time, peak.kind, peak.level), (5e-4, EventKind::Corner, 5.0));
    assert_eq!((peak.run.unwrap().v_from, peak.run.unwrap().v_to), (5.0, 0.0));
    let trough = sched.event(2).unwrap();
    assert_eq!((trough.time, trough.level), (1e-3, 0.0));
}

#[test]
fn pwl_knots_are_events_at_absolute_time_and_a_vertical_step_has_two_at_one_instant() {
    let (p, blob) = case("pwl/vertical-step"); // 0:0, 1e-3:5, 1e-3:2, 2e-3:2
    let sched = Schedule::new(p, blob);
    let e: Vec<SgEvent> = (0..5).filter_map(|k| sched.event(k)).collect();
    assert_eq!(e.len(), 4);
    assert_eq!(e.iter().map(|x| x.time).collect::<Vec<_>>(), vec![0.0, 1e-3, 1e-3, 2e-3]);
    assert_eq!(e.iter().map(|x| x.level).collect::<Vec<_>>(), vec![0.0, 5.0, 2.0, 2.0]);
    assert!(e.iter().all(|x| x.kind == EventKind::Knot));
    // The step's first knot starts a run to the second at the same instant: length 0, so no run.
    assert!(e[1].run.is_none());
    assert_eq!((e[0].run.unwrap().v_from, e[0].run.unwrap().v_to), (0.0, 5.0));
    // Before the first knot the output holds the first value.
    assert_eq!(sched.load_state(-1.0).0.value, 0.0);
    assert_eq!(sched.first_event_after(-1.0), Some(0));
    // The 70-point table keeps 64 knots.
    let (p, blob) = case("pwl/70-points-capped");
    let sched = Schedule::new(p, blob);
    assert!(sched.event(63).is_some());
    assert!(sched.event(64).is_none());
}

#[test]
fn noise_buckets_are_one_event_each_100_us_from_the_delay_a_picosecond_early() {
    let (p, blob) = case("noise/seed-2"); // delay 3.3e-4
    let sched = Schedule::new(p, blob);
    let e0 = sched.event(0).unwrap();
    assert_eq!(e0.kind, EventKind::Bucket);
    assert_eq!(e0.time, (3.3e-4 + 1.0 * 1e-4) - 1e-12);
    let unit = noise_unit(p[SEED], 1.0);
    assert_eq!(e0.level, p[OFFSET] + p[AMPLITUDE] * unit);
    // Load at t0 inside bucket 3 has applied buckets 1 to 3.
    let t0 = 3.3e-4 + 3.5e-4 + 1e-5;
    let (level, next) = sched.load_state(t0);
    assert_eq!(next, Some(3));
    assert_eq!(level.value, p[OFFSET] + p[AMPLITUDE] * noise_unit(p[SEED], 3.0));
    // Bucket 0 holds from t = 0, through the delay.
    let (level, next) = sched.load_state(0.0);
    assert_eq!(next, Some(0));
    assert_eq!(level.value, p[OFFSET] + p[AMPLITUDE] * noise_unit(p[SEED], 0.0));
}

#[test]
fn a_pulse_schedule_is_the_w1f_one_with_the_delay_as_td_and_the_period_as_one_over_f() {
    // Default: 1 us ramps against a 500 us top are midpoint steps (Q5): rise at tr/2, fall at tr + pw + tf/2.
    let (p, blob) = case("pulse/default");
    let sched = Schedule::new(p, blob);
    let rise = sched.event(0).unwrap();
    assert_eq!((rise.time, rise.kind, rise.level), (1e-6 / 2.0, EventKind::Edge, 5.0));
    let fall = sched.event(1).unwrap();
    assert_eq!((fall.time, fall.level), (((1e-6 + 5e-4) + 1e-6 / 2.0), 0.0));
    let next_rise = sched.event(2).unwrap();
    assert_eq!(next_rise.time, (0.0 + 1.0 * (1.0 / 1000.0)) + 1e-6 / 2.0);
    // Slow ramps resolve: start, mid, end for the rise, then for the fall.
    let (p, blob) = case("pulse/slow-ramps");
    let sched = Schedule::new(p, blob);
    let kinds: Vec<EventKind> = (0..6).map(|k| sched.event(k).unwrap().kind).collect();
    assert_eq!(kinds, vec![EventKind::Corner, EventKind::Mid, EventKind::Corner, EventKind::Corner, EventKind::Mid, EventKind::Corner]);
    let start = sched.event(0).unwrap();
    assert_eq!((start.time, start.level), (0.0, 0.0));
    let run = start.run.unwrap();
    assert_eq!((run.v_from, run.v_to, run.len), (0.0, 5.0, 1e-4));
}

