// ---- the reader check ----------------------------------------------------------------------------------------------

fn check(params: &[f64; 13], blob: &[f64]) -> Result<(), String> {
    signal_gen_check(0, params, blob)
}

#[test]
fn the_reader_accepts_every_golden_case() {
    for c in CASES {
        check(&c.1, c.2).unwrap_or_else(|e| panic!("{}: {e}", c.0));
    }
}

#[test]
fn the_reader_rejects_a_non_finite_value_in_any_param() {
    for i in 0..COUNT {
        for bad in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
            let mut p = params_of(SHAPE_SINE, &[]);
            p[i] = bad;
            assert!(check(&p, &[0.0]).is_err(), "param {i} = {bad}");
        }
    }
}

#[test]
fn the_reader_rejects_a_truncated_pulse_cycle_only_for_a_pulse() {
    // tr + pw + tf = 2.002 ms in a 1 ms period.
    let pulse = params_of(SHAPE_PULSE, &[(PW, 2e-3)]);
    assert!(check(&pulse, &[0.0]).unwrap_err().contains("truncated"));
    for shape in [SHAPE_DC, SHAPE_SINE, SHAPE_SQUARE, SHAPE_TRIANGLE, SHAPE_RAMP, SHAPE_NOISE] {
        assert!(check(&params_of(shape, &[(PW, 2e-3)]), &[0.0]).is_ok(), "shape {shape}");
    }
    // A cycle that fills the period exactly is whole.
    let exact = params_of(SHAPE_PULSE, &[(TR, 2.5e-4), (PW, 5e-4), (TF, 2.5e-4)]);
    assert!(check(&exact, &[0.0]).is_ok());
    // (0.1 + 0.2) + 0.3 is one ulp above 0.6: a 0.6 s period is truncated, as classic's `tr + pw + tf` sums.
    let sum = params_of(SHAPE_PULSE, &[(FREQUENCY, 1.0 / 0.6), (TR, 0.1), (PW, 0.2), (TF, 0.3)]);
    assert!(check(&sum, &[0.0]).unwrap_err().contains("truncated"));
}

#[test]
fn the_reader_rejects_a_seed_js_would_spell_in_exponent_form() {
    assert!(check(&params_of(SHAPE_NOISE, &[(SEED, 1e21)]), &[0.0]).is_err());
    assert!(check(&params_of(SHAPE_NOISE, &[(SEED, -1e21)]), &[0.0]).is_err());
    assert!(check(&params_of(SHAPE_NOISE, &[(SEED, 1e20)]), &[0.0]).is_ok());
}

#[test]
fn the_reader_rejects_a_non_finite_pwl_value_and_keeps_the_old_rules() {
    let p = params_of(SHAPE_PWL, &[]);
    assert!(check(&p, &[1.0, 0.0, f64::NAN]).is_err());
    assert!(check(&p, &[1.0, f64::INFINITY, 0.0]).is_err());
    assert!(check(&p, &[2.0, 1.0, 0.0, 0.5, 0.0]).is_err()); // times fall
    assert!(check(&p, &[2.0, 0.0, 0.0, 0.5, 5.0]).is_ok());
    assert!(check(&params_of(SHAPE_SINE, &[]), &[1.0, 0.0, 0.0]).is_err()); // points for a non-pwl shape
    assert!(check(&params_of(9, &[]), &[0.0]).is_err());
}

#[test]
fn a_square_fall_never_lands_after_the_next_rise_where_the_period_is_a_few_ulps_of_the_time() {
    // 10 MHz at duty 0.99 and 3e7 s: the fall is 1e-9 s short of the next rise, a third of an ulp of the time
    // (3.7e-9 s), so `rise + duty P` can round past `origin + (n + 1) P`. The clock's own case (Sources point 2).
    let p = params_of(SHAPE_SQUARE, &[(FREQUENCY, 1e7), (DUTY, 0.99)]);
    let sched = Schedule::new(&p, &[0.0]);
    let from = sched.first_event_after(3e7).unwrap();
    let events = walk(&sched, from, 400);
    assert_eq!(events.len(), 400);
    assert!(events.windows(2).all(|w| w[1].time >= w[0].time));
    // Alternating levels survive the clamp: falls and rises still pair up.
    assert!(events.windows(2).all(|w| w[0].level != w[1].level));
}

// ---- verifier fixes (9fca35e): the state just after the delay, long timelines, finite levels ------------------

/// Classic's reading in the middle of the stretch between the delay and the first event after it, against the
/// state `load_state(delay)` names. `None` when they agree (or there is no such stretch to probe).
fn after_delay_mismatch(params: &[f64; 13]) -> Option<String> {
    let sched = Schedule::new(params, &[0.0]);
    let delay = params[DELAY];
    let (level, next) = sched.load_state(delay);
    let first = sched.event(next?)?.time;
    let mid = delay + (first - delay) / 2.0;
    // A stretch shorter than the rounding of the edge times themselves (a few ulps of `delay` or of the period,
    // whichever is larger) has no interior classic's own float arithmetic can resolve.
    let scale = first.abs().max(1.0 / params[FREQUENCY]);
    if !(mid > delay && mid < first) || first - delay < 64.0 * f64::EPSILON * scale {
        return None;
    }
    let got = sched.voltage(mid);
    let swing = 2.0 * params[AMPLITUDE];
    let (want, tol) = match level.run {
        Some(run) => (run.value(mid), 1e-6 * swing),
        None => (level.value, 0.0),
    };
    ((got - want).abs() > tol).then(|| format!("{params:?}: classic reads {got:e} at {mid:e}, the schedule {want:e}"))
}

#[test]
fn a_square_edge_that_rounds_onto_the_delay_is_not_lost() {
    // Repro A: 50 Hz, phase 720, delay 0.5. The rise computes to the delay itself while classic's t' = 0 reading
    // sits just before it (LOW); classic is HIGH on [0.5, 0.51).
    let a = params_of(SHAPE_SQUARE, &[(FREQUENCY, 50.0), (PHASE_DEG, 720.0), (DELAY, 0.5)]);
    assert_eq!(after_delay_mismatch(&a), None);
    let sched = Schedule::new(&a, &[0.0]);
    assert_eq!(sched.voltage(0.505), 5.0);
    assert_eq!(sched.load_state(0.505).0.value, 5.0);
    // Before the delay the generator still holds classic's t' = 0 reading, and the edge is still to come.
    assert_eq!(sched.load_state(0.4).0.value, sched.voltage(0.4));
    // Repro B.
    let b = params_of(SHAPE_SQUARE, &[(FREQUENCY, 100.0), (PHASE_DEG, 180.0), (DELAY, 0.05)]);
    assert_eq!(after_delay_mismatch(&b), None);
}

#[test]
fn the_state_after_the_delay_is_classics_for_every_round_number_square_triangle_ramp_and_pulse() {
    let mut bad = Vec::new();
    let mut n = 0;
    for shape in [SHAPE_SQUARE, SHAPE_TRIANGLE, SHAPE_RAMP, SHAPE_PULSE] {
        for f in [1.0, 2.0, 3.0, 5.0, 7.0, 10.0, 20.0, 50.0, 100.0, 200.0, 500.0, 1000.0, 1e4] {
            for phase in [0.0, 30.0, 45.0, 60.0, 90.0, 120.0, 180.0, 210.0, 270.0, 300.0, 360.0, 450.0, 540.0, 630.0, 720.0, -90.0, -180.0, -360.0, -450.0, -630.0] {
                for delay in [0.0, 1e-5, 1e-3, 0.01, 0.05, 0.1, 0.125, 0.2, 0.25, 0.3, 0.5, 0.7, 1.0, 2.0, 5.0, 2.2e-3, 3.3e-4, 10.0, 123.456] {
                    for duty in if shape == SHAPE_SQUARE { vec![0.1, 0.25, 0.5, 0.75, 0.9] } else { vec![0.5] } {
                        let p = params_of(
                            shape,
                            &[(FREQUENCY, f), (PHASE_DEG, phase), (DELAY, delay), (DUTY, duty), (PW, 0.2 / f), (TR, 0.1 / f), (TF, 0.1 / f)],
                        );
                        n += 1;
                        bad.extend(after_delay_mismatch(&p));
                    }
                }
            }
        }
    }
    assert!(n > 30_000);
    assert!(bad.is_empty(), "{} of {n} configs wrong, first: {:?}", bad.len(), &bad[..bad.len().min(4)]);
}

#[test]
fn the_reader_declines_a_delay_whose_ulp_nears_the_period() {
    // Rule: ulp(delay) <= period * 2^-20, for the shapes with a schedule (square, triangle, ramp, pulse at 1/f;
    // noise at 1e-4 s). 1 kHz: the limit is 9.5e-10 s of ulp, a delay under about 4e6 s; ulp(1e13) = 1.9e-3 is far
    // past it and ulp(1e6) = 1.2e-10 well inside.
    for shape in [SHAPE_SQUARE, SHAPE_TRIANGLE, SHAPE_RAMP] {
        assert!(check(&params_of(shape, &[(DELAY, 1e13)]), &[0.0]).unwrap_err().contains("delay"), "shape {shape}");
        assert!(check(&params_of(shape, &[(DELAY, 1e6)]), &[0.0]).is_ok(), "shape {shape}");
    }
    assert!(check(&params_of(SHAPE_PULSE, &[(DELAY, 1e13)]), &[0.0]).is_err());
    // Noise: period 1e-4, so the limit is ulp(delay) <= 9.5e-11, a delay under 2^19 s.
    assert!(check(&params_of(SHAPE_NOISE, &[(DELAY, 1e6)]), &[0.0]).is_err());
    assert!(check(&params_of(SHAPE_NOISE, &[(DELAY, 3e5)]), &[0.0]).is_ok());
    // A slow generator tolerates a late delay in proportion: 1e-3 Hz is a 1000 s period.
    assert!(check(&params_of(SHAPE_SQUARE, &[(FREQUENCY, 1e-3), (DELAY, 1e12)]), &[0.0]).is_ok());
    // Shapes with no lattice have no such limit.
    for shape in [SHAPE_DC, SHAPE_SINE] {
        assert!(check(&params_of(shape, &[(DELAY, 1e13)]), &[0.0]).is_ok(), "shape {shape}");
    }
}

#[test]
fn the_reader_declines_levels_that_overflow_or_would_overflow_a_line() {
    // offset +- amplitude reaching infinity, and noise's draws (up to about 6.8 sigma) times the amplitude.
    for shape in [SHAPE_SINE, SHAPE_SQUARE, SHAPE_TRIANGLE, SHAPE_RAMP, SHAPE_PULSE, SHAPE_NOISE] {
        assert!(check(&params_of(shape, &[(OFFSET, 1e308), (AMPLITUDE, 1e308)]), &[0.0]).is_err(), "shape {shape}");
        assert!(check(&params_of(shape, &[(AMPLITUDE, 1e150)]), &[0.0]).is_err(), "shape {shape}");
    }
    assert!(check(&params_of(SHAPE_DC, &[(OFFSET, 1e308)]), &[0.0]).is_err());
    // A dc source ignores the amplitude and a table the offset and amplitude, as classic does.
    assert!(check(&params_of(SHAPE_DC, &[(AMPLITUDE, 1e308)]), &[0.0]).is_ok());
    let pwl = params_of(SHAPE_PWL, &[(OFFSET, 1.0), (AMPLITUDE, 1e308)]);
    assert!(check(&pwl, &[2.0, 0.0, 1e308, 1.0, -1e308]).is_err());
    assert!(check(&pwl, &[2.0, 0.0, 1e90, 1.0, -1e90]).is_ok());
    // PWL times far enough apart for a segment length to overflow.
    assert!(check(&pwl, &[2.0, -1e308, 0.0, 1e308, 1.0]).is_err());
}

#[test]
fn a_square_edge_that_rounds_just_after_the_delay_while_the_hold_is_already_past_it_adds_no_start() {
    // The mirror of repro A: 1 Hz, phase 270, duty 0.75, delay 3.3e-4. The fall is due at the delay and computes
    // 5e-17 s after it, but classic's t' = 0 reading is already LOW: a Start carrying the previous HIGH would
    // drive a spurious 5e-17 s pulse.
    let p = params_of(SHAPE_SQUARE, &[(FREQUENCY, 1.0), (PHASE_DEG, 270.0), (DUTY, 0.75), (DELAY, 3.3e-4)]);
    let sched = Schedule::new(&p, &[0.0]);
    let first = sched.event(0).unwrap();
    assert_eq!(first.kind, EventKind::Edge);
    assert!(first.time > 3.3e-4 && first.time < 3.3e-4 + 1e-12);
    assert_eq!(sched.load_state(3.3e-4).0.value, 0.0);
    assert_eq!(sched.voltage(3.3e-4 + 1e-3), 0.0);
}
